[Form]
public class GUPVendPriceAdm extends FormRun
{
    #ResAppl
    Map                     lineMessage;
    InventDimCtrl_Frm       inventDimFormSetup;
    InventDimParm           inventDimParmPriceSetup;
    InventDimParm           inventDimParmPriceWarning;
    boolean                 initFromGUPVendPriceAdmTrans;
    Object                  callerObject;
    ImageListAppl_Infolog   imageList;
    int64                   messageId = 0;
    int64                   warningId = 0;
    NumberSeqFormHandler    numberSeqFormHandler;

}

NumberSeqFormHandler numberSeqFormHandler()
{
    if (! numberSeqFormHandler)
    {
        numberSeqFormHandler = NumberSeqFormHandler::newForm(GUPParameters::numRefVendPriceJournalNum().NumberSequenceId,
                                                             element,
                                                             GUPVendPriceAdmTable_ds,
                                                             fieldNum(GUPVendPriceAdmTable, JournalNum));
    }
    return numberSeqFormHandler;
}

    public void close()
    {
        if (numberSeqFormHandler)
        {
            numberSeqFormHandler.formMethodClose();
        }

        super();
    }

    void  initRecord()
    {
        GUPVendPriceAdmTrans.initFromItemCode();

        if (GUPVendPriceAdmTrans.AccountCode == TableGroupAll::All)
        {
            GUPVendPriceAdmTrans_ds.object(fieldNum(GUPVendPriceAdmTrans, AccountRelation)).skip(true);
            GUPVendPriceAdmTrans_ds.object(fieldNum(GUPVendPriceAdmTrans, AccountRelation)).allowEdit(false);
        }
        else
        {
            GUPVendPriceAdmTrans_ds.object(fieldNum(GUPVendPriceAdmTrans, AccountRelation)).skip(false);
            GUPVendPriceAdmTrans_ds.object(fieldNum(GUPVendPriceAdmTrans, AccountRelation)).allowEdit(true);
        }
    }

    void updateDesign(InventDimFormDesignUpdate mode)
    {
        InventDimParm           inventDimParmVisible;
        InventDimParm           inventDimParmEnabled;
        InventDimGroupSetup     inventDimGroupSetup;
        InventTable             localInventTable;

        switch (mode)
        {
            case InventDimFormDesignUpdate::Init          :
            case InventDimFormDesignUpdate::LinkActive    :
                
                if (! inventDimFormSetup)
                {
                    inventDimFormSetup  = InventDimCtrl::newFromForm(element);
                }

                inventDimFormSetup.parmSkipOnHandLookUp(true);

                inventDimParmVisible.initPriceDiscDimAllGrp();
                inventDimFormSetup.parmDimParmVisibleGrid(inventDimParmVisible);

            case InventDimFormDesignUpdate::Active        :

                inventDimFormSetup.formActiveSetup();

                if (GUPVendPriceAdmTrans.ItemNum)
                {
                    localInventTable    = InventTable::find(GUPVendPriceAdmTrans.ItemNum);
                    inventDimGroupSetup = InventDimGroupSetup::newDimensionGroups(localInventTable.productDimensionGroup(),
                                                                                  localInventTable.storageDimensionGroup(),
                                                                                  localInventTable.trackingDimensionGroup());
                    
                    inventDimGroupSetup.inventDimParmActive(inventDimParmEnabled);
                    inventDimGroupSetup.inventDimParmActivePurchPrice(inventDimParmPriceSetup);
                }
                else
                {
                    inventDimParmEnabled.clear();
                    inventDimParmPriceSetup.clear();
                }

                inventDimFormSetup.parmDimParmEnabled(inventDimParmEnabled);
                inventDimFormSetup.formSetControls(true);

                inventDimParmPriceWarning.initFromInventDim(inventDim);
                inventDimParmPriceWarning = InventDimParm::xorParms(inventDimParmPriceWarning, inventDimParmPriceSetup);
                
                this.setReferenceText();

                break;

            case InventDimFormDesignUpdate::FieldChange   :
                inventDimFormSetup.formActiveSetup();

                if (GUPVendPriceAdmTrans.ItemNum)
                {
                    localInventTable    = InventTable::find(GUPVendPriceAdmTrans.ItemNum);
                    
                    inventDimGroupSetup = InventDimGroupSetup::newDimensionGroups(localInventTable.productDimensionGroup(),
                                                                                  localInventTable.storageDimensionGroup(),
                                                                                  localInventTable.trackingDimensionGroup());

                    inventDimGroupSetup.inventDimParmActive(inventDimParmEnabled);
                }
                else
                {
                    inventDimParmEnabled.clear();
                }

                inventDimFormSetup.parmDimParmEnabled(inventDimParmEnabled);
                inventDimFormSetup.formSetControls(false);
                break;

            default : throw error(strFmt("@SYS54195",funcName()));
        }
    }

    public void doActiveButtons(boolean _enableDeleteButton = GUPVendPriceAdmTrans.RecId)
    {
        boolean enabled = (GUPVendPriceAdmTable.Status == GUPDisabledEnabled::Disabled);
        str textValue = enabled ? "@SYS70338" : "@SYS70337";

        GUPVendPriceAdmAdjustPrice.enabled(enabled);
        GUPVendPriceAdmSmartRound.enabled(enabled);

        GUPVendPriceAdmCopy.enabled(enabled);
        GUPVendPriceAdmCopyLine.enabled(enabled);

        GUPVendPriceAdmTable_ds.allowDelete(enabled);

        GUPVendPriceAdmTrans_ds.allowEdit(enabled);
        GUPVendPriceAdmTrans_ds.allowCreate(enabled);
        GUPVendPriceAdmTrans_ds.allowDelete(enabled);

        EnableDisable.text(textValue);
    }

    int checkLines(GUPVendPriceAdmTrans _vendPriceAdmTrans)
    {
        InventDimParm        inventDimParmAll,
                             inventDimParmItem,
                             inventDimParmInventDim;
        InventDim            inventDimLocal,
                             inventDimAll,
                             inventDimItem,
                             inventDimBlank;
        InventTable          inventTable;
        InventDimGroupSetup  inventDimGroupSetup;

        if (_vendPriceAdmTrans.ItemNum)
        {
            inventDimLocal = InventDim::find(_vendPriceAdmTrans.InventDimId);

            if (InventDim::isInventDimEqual(inventDimBlank,inventDimLocal))
            {
                return -1;
            }

            inventTable         = InventTable::find(_vendPriceAdmTrans.ItemNum);
            inventDimGroupSetup = InventDimGroupSetup::newInventTable(inventTable);

            inventDimGroupSetup.inventDimParmActive(inventDimParmAll);
            inventDimGroupSetup.inventDimParmActiveProductDimension(inventDimParmItem);
            
            inventDimAll.copyDimParmDim(inventDimGroupSetup, inventDimLocal, inventDimParmAll);
            inventDimItem.copyDimParmDim(inventDimGroupSetup, inventDimLocal, inventDimParmItem);

            if  (! inventDimParmAll.isInventDimEqualInventDimParm(inventDimAll) || ! inventDimParmItem.isInventDimEqualInventDimParm(inventDimItem))
            {
                return imageList.image(#ImageError);
            }

            inventDimParmInventDim.initFromInventDim(inventDimLocal);

            if (! InventDimParm::isInventDimParmEqual(inventDimParmInventDim, inventDimParmAll) && ! InventDimParm::isInventDimParmEqual(inventDimParmInventDim, inventDimParmItem))
            {
                return imageList.image(#ImageWarning);
            }
        }

        return -1;
    }

    void setReferenceText()
    {
        if (messageId)
        {
            Message::Remove(messageId);
        }

        if (inventDimParmPriceSetup.toString())
        {
            messageId = Message::Add(MessageSeverity::Informational, strFmt("@SYS70184", inventDimParmPriceSetup.toString()));
        }
        else
        {
            messageId = Message::Add(MessageSeverity::Informational, "@SYS70185");
        }

        if (warningId)
        {
            Message::Remove(warningId);
        }

        if (! lineMessage.exists(GUPVendPriceAdmTrans.RecId))
        {
            lineMessage.insert(GUPVendPriceAdmTrans.RecId, element.checkLines(GUPVendPriceAdmTrans));
        }

        if (lineMessage.lookup(GUPVendPriceAdmTrans.RecId) != -1 && inventDimParmPriceWarning.toString())
        {
            warningId = Message::Add(MessageSeverity::Warning, strFmt("@SYS70190", inventDimParmPriceWarning.toString()));
        }
    }

Object inventDimSetupObject()
{
    return inventDimFormSetup;
}

ItemId itemId()
{
    return GUPVendPriceAdmTrans.itemId();
}

    public void init()
    {
        super();

        element.doActiveButtons();
        
        imageList = new ImageListAppl_Infolog();
        priceIcon.imageList(imageList.imageList());

        lineMessage = new Map(typeName2Type(extendedTypeStr(RecId)), Types::Integer);

        messageId = Message::Add(MessageSeverity::Informational, "@SYS70185");

        if (warningId)
        {
            Message::Remove(warningId);
        }

        element.updateDesign(InventDimFormDesignUpdate::Init);
    }

    public void enableHeaderFields()
    {
        boolean enabled = (GUPVendPriceAdmTable.Status == GUPDisabledEnabled::Disabled);
        boolean allowEditAccountRelation = GUPVendPriceAdmTable.AccountCode != TableGroupAll::All;

        GUPVendPriceAdmTable_ds.object(fieldNum(GUPVendPriceAdmTable, AccountRelation)).skip(!allowEditAccountRelation);
        GUPVendPriceAdmTable_ds.object(fieldNum(GUPVendPriceAdmTable, AccountRelation)).allowEdit(enabled && allowEditAccountRelation);
    }

        public void linkActive()
        {
            element.numberSeqFormHandler().formMethodDataSourceLinkActive();

            super();
        }

        public boolean validateWrite()
        {
            boolean ret;
        
            ret = super();

            ret = element.numberSeqFormHandler().formMethodDataSourceValidateWrite(ret) && ret;
        
            return ret;
        }

        public void write()
        {
            ttsbegin;

            super();

            element.numberSeqFormHandler().formMethodDataSourceWrite();
            
            ttscommit;
        }

        public void delete()
        {
            ttsbegin;

            element.numberSeqFormHandler().formMethodDataSourceDelete();

            super();

            ttscommit;
        }

        public void create(boolean _append = false)
        {
            element.numberSeqFormHandler().formMethodDataSourceCreatePre();

            super(_append);

            element.numberSeqFormHandler().formMethodDataSourceCreate(true);
        }

        public int active()
        {
            int ret;
        
            ret = super();
        
            element.doActiveButtons();
            element.enableHeaderFields();

            return ret;
        }

            public void modified()
            {
                super();

                element.enableHeaderFields();
            }

            public void modified()
            {
                super();

                element.doActiveButtons();
            }

        public void create(boolean _append = false)
        {
            GUPVendPriceAdmTrans localGUPVendPriceAdmTrans;

            localGUPVendPriceAdmTrans.data(GUPVendPriceAdmTrans);

            super(_append);

            if (initFromGUPVendPriceAdmTrans)
            {
                GUPVendPriceAdmTrans.initFromGUPVendPriceAdmTrans(localGUPVendPriceAdmTrans);
                inventDim.data(GUPVendPriceAdmTrans.inventDim());
                initFromGUPVendPriceAdmTrans = false;
            }
        }

        public boolean validateWrite()
        {
            boolean ret;

            GUPVendPriceAdmTrans.InventDimId = InventDim::findOrCreate(inventDim).InventDimId;

            ret = super();

            return ret;
        }

        public void write()
        {
            InventDim newInventDim = InventDim::findOrCreate(inventDim);
            
            GUPVendPriceAdmTrans.InventDimId = newInventDim.InventDimId;

            super();

            if (lineMessage.exists(GUPVendPriceAdmTrans.RecId))
            {
                lineMessage.remove(GUPVendPriceAdmTrans.RecId);
            }

            if (GUPVendPriceAdmTrans.InventDimId != inventDim.InventDimId)
            {
                inventDim.data(newInventDim);
                inventDim_ds.setCurrent();
            }
        }

        public int active()
        {
            int ret;
        
            ret = super();

            element.initRecord();
            element.updateDesign(InventDimFormDesignUpdate::Active);

            return ret;
        }

        void initValue()
        {
            super();

            GUPVendPriceAdmTrans.initFromGUPVendPriceAdmTable(GUPVendPriceAdmTable);
            GUPVendPriceAdmTrans.Currency = Ledger::accountingCurrency(CompanyInfo::current());

            inventDim.data(GUPVendPriceAdmTrans.inventDim());
        }

        display ImageRes checkIfLines(GUPVendPriceAdmTrans _vendPriceAdmTrans)
        {
            if (! lineMessage.exists(_vendPriceAdmTrans.RecId))
            {
                lineMessage.insert(_vendPriceAdmTrans.RecId,element.checkLines(_vendPriceAdmTrans));
            }

            return lineMessage.lookup(_vendPriceAdmTrans.RecId);
        }

        public void linkActive()
        {
            super();

            element.updateDesign(InventDimFormDesignUpdate::LinkActive);
        }

            public void modified()
            {
                super();

                element.initRecord();
            }

            public void modified()
            {
                super();

                GUPVendPriceAdmTrans.initFromAccountCode();
            }

            public void modified()
            {
                InventDim   inventDimBlank;

                super();

                if (!GUPVendPriceAdmTrans.InventDimId)
                {
                    inventDimBlank                   = InventDim::find(InventDim::inventDimIdBlank());
                    GUPVendPriceAdmTrans.InventDimId = inventDimBlank.InventDimId;
                
                    inventDim.data(inventDimBlank);
                }

                element.updateDesign(InventDimFormDesignUpdate::FieldChange);
            }

            public void lookup(FormControl _formControl, str _filterStr)
            {
                GUPVendPriceAdmTrans.InventDimId = InventDim::findOrCreate(inventDim).InventDimId;

                super(_formControl, _filterStr);
            }

public void write()
