}

        public void clicked()
        {
            super();

            boolean isEnabled = (GUPVendPriceAdmTable.Status == GUPDisabledEnabled::Enabled);
            str labelValue = isEnabled ? "@GlobalUnifiedPricing:GUPVendPriceAdm_infolog_disable" : "@GlobalUnifiedPricing:GUPVendPriceAdm_infolog_enable";

            ttsbegin;
            GUPVendPriceAdmTable.Status = isEnabled ? GUPDisabledEnabled::Disabled : GUPDisabledEnabled::Enabled;
            GUPVendPriceAdmTable.update();
            ttscommit;

            GUPVendPriceAdmTable_ds.reread();
            element.doActiveButtons();

            info(strFmt(labelValue, GUPVendPriceAdmTable.JournalNum));
        }

public void clicked()
{
    initFromGUPVendPriceAdmTrans = true;
    super();
    GUPVendPriceAdmTrans_DS.create();
}

    public str toolTip()
    {
        str ret;

        switch (GUPVendPriceAdmTrans_ds.checkIfLines(GUPVendPriceAdmTrans))
        {
            case imageList.image(#ImageWarning) : ret = "@SYS70189"; break;
            case imageList.image(#ImageError)   : ret = "@SYS70186"; break;
        }

        return ret;
    }
